194	// decodeJSONBody enforces the strict POST contract shared by every JSON
195	// endpoint: Content-Type must be application/json, the body is capped at
196	// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
197	// may follow it. Any violation writes a 400 JSON error and returns false; the
198	// caller returns immediately, so no handler reaches the store with malformed
199	// input and rejected requests write nothing.
200	func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
201		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
202		if err != nil || mediaType != "application/json" {
203			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
204			return false
205		}
206	
207		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
208		dec := json.NewDecoder(r.Body)
209		if err := dec.Decode(dst); err != nil {
210			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
211			return false
212		}
213		// Reject trailing data after the JSON value.
214		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
215			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
216			return false
217		}
218		return true
219	}
