318		for i, c := range req.Changes {
319			if c.ID == "" {
320				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
321				return
322			}
323			if len(c.Payload) == 0 {
324				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
325				return
326			}
327			if _, dup := seen[c.ID]; dup {
328				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
329				return
330			}
331			seen[c.ID] = struct{}{}
332			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
333		}
334	
335		results, err := s.PostChanges(documentID, changes)
336		if err != nil {
337			var conflict *store.ErrConflict
338			if errors.As(err, &conflict) {
339				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
340				return
341			}
342			writeError(w, http.StatusInternalServerError, "failed to commit changes")
343			return
344		}
345	
346		writeJSON(w, http.StatusOK, map[string]any{"results": results})
347	}
348	
349	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
350		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
351	
352		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
353		if err != nil || mediaType != "application/json" {
354			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
355			return
356		}
357	
358		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
359		var req mergeRequest
360		dec := json.NewDecoder(r.Body)
361		if err := dec.Decode(&req); err != nil {
362			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
363			return
364		}
365		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
366			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
367			return
368		}
369	
370		if req.DeviceID == "" {
371			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
372			return
373		}
374		// baseCursor must be present and a non-negative integer (no fractions,
375		// strings, booleans or null).
376		if len(req.BaseCursor) == 0 {
377			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
378			return
379		}
380		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
381		if !ok {
382			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
383			return
384		}
385		if req.Change == nil {
386			writeError(w, http.StatusBadRequest, "change must be an object")
387			return
388		}
389		if req.Change.ID == "" {
390			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
391			return
392		}
393		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
394			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
395			return
396		}
397	
398		result, err := s.MergeChange(documentID, baseCursor, store.Change{
399			ID:       req.Change.ID,
400			DeviceID: req.DeviceID,
401			Payload:  req.Change.Payload,
402		})
403		if err != nil {
404			var conflict *store.ErrConflict
405			switch {
406			case errors.Is(err, store.ErrStaleCursor):
407				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
408				return
409			case errors.As(err, &conflict):
410				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
411				return
412			default:
413				writeError(w, http.StatusInternalServerError, "failed to merge change")
414				return
415			}
416		}
417	
418		writeJSON(w, http.StatusOK, result)
419	}
420	
421	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
422		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
423	
424		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
425		if err != nil || mediaType != "application/json" {
426			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
427			return
428		}
429	
430		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
431		var req snapshotPostRequest
432		dec := json.NewDecoder(r.Body)
433		if err := dec.Decode(&req); err != nil {
434			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
435			return
436		}
437		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
438			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
439			return
440		}
441	
442		cursor, ok := parseNonNegativeInt(req.Cursor)
443		if !ok {
444			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
445			return
446		}
447		if len(req.State) == 0 {
448			writeError(w, http.StatusBadRequest, "state is required")
449			return
450		}
451	
452		created, err := s.PutSnapshot(documentID, cursor, req.State)
453		if err != nil {
454			var conflict *store.ErrSnapshotConflict
455			switch {
456			case errors.Is(err, store.ErrSnapshotBase):
457				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
458				return
459			case errors.As(err, &conflict):
460				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
461				return
462			default:
463				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
464				return
465			}
466		}
467	
468		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
469	}
470	
471	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
472		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
473	
474		cursor, ok := parseCursorPath(r.PathValue("cursor"))
475		if !ok {
476			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
477			return
478		}
479	
480		state, err := s.GetSnapshot(documentID, cursor)
481		if err != nil {
482			if errors.Is(err, store.ErrSnapshotNotFound) {
483				writeError(w, http.StatusNotFound, "snapshot not found")
484				return
485			}
486			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
487			return
488		}
489	
490		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
491	}
492	
493	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
494		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
495	
496		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
497		if err != nil || mediaType != "application/json" {
498			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
499			return
500		}
501	
502		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
503		var req restoreRequest
504		dec := json.NewDecoder(r.Body)
505		if err := dec.Decode(&req); err != nil {
506			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
507			return
508		}
509		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
510			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
511			return
512		}
513	
514		if req.DeviceID == "" {
515			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
516			return
517		}
518		if req.ChangeID == "" {
519			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
520			return
521		}
522		// snapshotCursor must be present and a positive integer (no fractions,
523		// strings, booleans, null or zero).
524		if len(req.SnapshotCursor) == 0 {
525			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
526			return
527		}
528		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
529		if !ok {
530			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
531			return
532		}
533	
534		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
535		if err != nil {
536			var conflict *store.ErrRestoreConflict
537			switch {
538			case errors.Is(err, store.ErrSnapshotNotFound):
539				writeError(w, http.StatusNotFound, "snapshot not found")
540				return
541			case errors.As(err, &conflict):
542				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
543				return
544			default:
545				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
546				return
547			}
548		}
549	
550		writeJSON(w, http.StatusOK, result)
551	}
552	
553	// handleSetPermission grants or revokes a registered device's access to one
554	// document. Devices start authorized, so the first revoke is the first write;
555	// repeating the current state is idempotent (changed=false). A rejected
556	// request (bad content type, malformed JSON, trailing content, empty or
557	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
558	// unregistered device is a 404 JSON error.
559	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
560		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
561	
562		var req permissionRequest
563		if !decodeJSONBody(w, r, &req) {
564			return
565		}
566		if req.DeviceID == "" {
567			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
568			return
569		}
570		var authorized bool
571		switch req.Action {
572		case "grant":
573			authorized = true
574		case "revoke":
575			authorized = false
576		default:
577			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
578			return
579		}
580	
581		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
582		if err != nil {
583			if errors.Is(err, store.ErrDeviceNotFound) {
584				writeError(w, http.StatusNotFound, "device not found")
585				return
586			}
587			writeError(w, http.StatusInternalServerError, "failed to update permission")
588			return
589		}
590	
591		writeJSON(w, http.StatusOK, map[string]any{
592			"deviceId":   req.DeviceID,
593			"authorized": authorized,
594			"changed":    changed,
595		})
596	}
597	
598	// parseCursorPath reports whether raw is a decimal non-negative integer and
599	// returns its value. Signs, fractions and other adornments are rejected.
600	func parseCursorPath(raw string) (int64, bool) {
601		if raw == "" {
602			return 0, false
603		}
604		for _, c := range raw {
605			if c < '0' || c > '9' {
606				return 0, false
607			}
608		}
609		n, err := strconv.ParseInt(raw, 10, 64)
610		if err != nil {
611			return 0, false
612		}
613		return n, true
614	}
615	
616	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
617	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
618		var n int64
619		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
620			return 0, false
621		}
622		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
623		// require the literal to contain no fraction or exponent.
624		trimmed := strings.TrimSpace(string(raw))
625		if trimmed == "" || trimmed[0] == '-' {
626			return 0, false
627		}
628		for _, c := range trimmed {
629			if c < '0' || c > '9' {
630				return 0, false
631			}
632		}
633		return n, true
634	}
635	
636	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
637	// strings, booleans, null and negative numbers are rejected.
638	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
639		n, ok := parseNonNegativeInt(raw)
640		if !ok || n < 1 {
641			return 0, false
642		}
643		return n, true
644	}
645	
646	// isJSONObject reports whether raw decodes to a JSON object (not null, an
647	// array or a scalar).
648	func isJSONObject(raw json.RawMessage) bool {
649		var m map[string]json.RawMessage
650		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
651			return false
652		}
653		return true
654	}
655	
656	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
657		documentID := r.PathValue("documentID")
658	
659		after, limit, ok := parseChangesQuery(w, r)
660		if !ok {
661			return
662		}
663	
664		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
665		if err != nil {
666			writeError(w, http.StatusInternalServerError, "failed to list changes")
667			return
668		}
669	
670		writeChangesPage(w, changes, nextCursor)
671	}
672	
673	// handleSessionChanges is the session-scoped view of the existing change log:
674	// both path identifiers must be non-empty (the empty-segment guard rejects
675	// those before routing) and the session must currently exist, after which the
676	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
677	// the session's device has been revoked permission for the document, which is
678	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
679	// read; the change log itself is untouched.
680	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
681		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
682		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
683	
684		// Malformed query parameters are a request-shape error (400) checked
685		// before the resource lookup (404), matching the snapshot GET ordering.
686		after, limit, ok := parseChangesQuery(w, r)
687		if !ok {
688			return
689		}
690	
691		deviceID, err := s.SessionDevice(sessionID)
692		if err != nil {
693			if errors.Is(err, store.ErrSessionNotFound) {
694				writeError(w, http.StatusNotFound, "session not found")
695				return
696			}
697			writeError(w, http.StatusInternalServerError, "failed to look up session")
698			return
699		}
700	
701		authorized, err := s.DocumentAuthorized(documentID, deviceID)
702		if err != nil {
703			writeError(w, http.StatusInternalServerError, "failed to look up permission")
704			return
705		}
706		if !authorized {
707			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
708			return
709		}
710	
711		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
712		if err != nil {
713			writeError(w, http.StatusInternalServerError, "failed to list changes")
714			return
715		}
716	
717		writeChangesPage(w, changes, nextCursor)
718	}
719	
720	// parseChangesQuery parses the shared after/limit pagination parameters,
721	// writing the documented 400 on an illegal value. It is shared by the
722	// document-scoped and session-scoped change listings so their query semantics
723	// cannot drift apart.
724	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
725		q := r.URL.Query()
726	
727		after = 0
728		if raw := q.Get("after"); raw != "" {
729			v, err := strconv.ParseInt(raw, 10, 64)
730			if err != nil || v < 0 {
731				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
732				return 0, 0, false
733			}
734			after = v
735		}
736	
737		limit = defaultListLimit
738		if raw := q.Get("limit"); raw != "" {
739			v, err := strconv.ParseInt(raw, 10, 64)
740			if err != nil || v < 1 || v > maxListLimit {
741				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
742				return 0, 0, false
743			}
744			limit = v
745		}
746	
747		return after, limit, true
748	}
749	
750	// writeChangesPage renders a change listing page in the shared response shape.
751	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
752		writeJSON(w, http.StatusOK, map[string]any{
753			"changes":    changes,
754			"nextCursor": nextCursor,
755		})
756	}
757	
758	func writeJSON(w http.ResponseWriter, status int, v any) {
759		w.Header().Set("Content-Type", "application/json")
760		w.WriteHeader(status)
761		_ = json.NewEncoder(w).Encode(v)
762	}
763	
764	func writeError(w http.ResponseWriter, status int, message string) {
765		writeJSON(w, status, map[string]string{"error": message})
766	}
