type process struct {
	cmd     *exec.Cmd
	out     *safeBuffer
	addr    string
	dataDir string
}

type safeBuffer struct {
	mu  sync.Mutex
	buf bytes.Buffer
}

func (s *safeBuffer) Write(p []byte) (int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.buf.Write(p)
}

func (s *safeBuffer) String() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.buf.String()
}

var listeningLine = regexp.MustCompile(`sync service listening on (\S+) \(data: (.*)\)`)

// startProcess launches syncd with the given environment and waits for the
// startup line, returning the actual endpoint parsed from it.
func startProcess(t *testing.T, env ...string) *process {
	t.Helper()
	p := &process{
		cmd: exec.Command(buildBinary(t)),
		out: &safeBuffer{},
	}
	p.cmd.Env = append(os.Environ(), env...)
	p.cmd.Stdout = p.out
	p.cmd.Stderr = p.out
	if err := p.cmd.Start(); err != nil {
		t.Fatalf("start syncd: %v", err)
	}

	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		if p.cmd.ProcessState != nil {
			break
		}
		if m := listeningLine.FindStringSubmatch(p.out.String()); m != nil {
			p.addr = m[1]
			p.dataDir = m[2]
			return p
		}
		time.Sleep(10 * time.Millisecond)
	}
	_ = p.cmd.Process.Kill()
	_ = p.cmd.Wait()
	t.Fatalf("syncd never reported its endpoint; output:\n%s", p.out.String())
	return nil
}

func (p *process) terminate(t *testing.T) int {
	t.Helper()
	if err := p.cmd.Process.Signal(syscall.SIGTERM); err != nil {
		t.Fatalf("send SIGTERM: %v", err)
	}
	waitErr := p.wait(10 * time.Second)
	if ee, ok := waitErr.(*exec.ExitError); ok {
		return ee.ExitCode()
	}
	if waitErr != nil {
		t.Fatalf("wait for syncd: %v", waitErr)
	}
	return 0
}

func (p *process) wait(d time.Duration) error {
	done := make(chan error, 1)
	go func() { done <- p.cmd.Wait() }()
	select {
	case err := <-done:
		return err
	case <-time.After(d):
		_ = p.cmd.Process.Kill()
		<-done
		return fmt.Errorf("process did not exit within %s", d)
	}
}

